"""
Mock Data Service
Handles importing mock data from JSON files
"""

import json
import logging
import os
from typing import List, Dict, Any, Optional
from app.core.database import get_database
from CEC_DocifyCode_Common.models.project import Project
from CEC_DocifyCode_Common.models.user import User

from app.services.logs_service import save_exception_log_sync

logger = logging.getLogger(__name__)


class MockDataService:
    """Service for importing mock data - Singleton pattern"""

    _instance = None
    _initialized = False

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(MockDataService, cls).__new__(cls)
        return cls._instance

    def __init__(self):
        if not MockDataService._initialized:
            self.project_collection_name = Project.Config.collection_name
            self.user_collection_name = User.Config.collection_name
            self._db = None
            MockDataService._initialized = True
            logger.info("[MockDataService] Singleton instance initialized")

    async def _get_database(self):
        """Get database instance (lazy initialization)"""
        if self._db is None:
            logger.debug(
                "[MockDataService._get_database] Initializing database connection"
            )
            self._db = await get_database()
        return self._db

    async def get_database_collection(self, collection_name: str):
        """Get database collection"""
        db = await self._get_database()
        return db.get_collection(collection_name)

    async def count_projects(self) -> int:
        """Count total projects in collection"""
        logger.info("[count_projects] Counting projects")
        try:
            collection = await self.get_database_collection(
                self.project_collection_name
            )
            count = await collection.count_documents(
                {"$or": [{"deleted_at": None}, {"deleted_at": {"$exists": False}}]}
            )
            logger.info(f"[count_projects] Found {count} projects")
            return count
        except Exception as e:
            error_message = f"[count_projects] Error counting projects: {e}"
            logger.error(error_message)
            save_exception_log_sync(e, error_message, __name__)

            raise

    async def import_project_mock_data(self) -> bool:
        """Import project mock data from JSON file"""
        logger.info("[import_project_mock_data] Starting project mock data import")
        try:
            # Check if projects already exist
            project_count = await self.count_projects()
            if project_count > 0:
                logger.info(
                    f"[import_project_mock_data] Found {project_count} existing projects. "
                    "Clearing collection before importing new data..."
                )
                # Clear existing data to ensure clean import with new structure
                collection = await self.get_database_collection(
                    self.project_collection_name
                )
                await collection.delete_many({})
                logger.info("[import_project_mock_data] Cleared existing projects")

            # Get path to mock data file
            current_dir = os.path.dirname(os.path.abspath(__file__))
            mock_data_path = os.path.join(
                current_dir, "..", "..", "mongodb-init", "mock-data", "project.json"
            )

            if not os.path.exists(mock_data_path):
                logger.error(
                    f"[import_project_mock_data] Mock data file not found: {mock_data_path}"
                )
                return False

            # Read and parse JSON file
            with open(mock_data_path, "r", encoding="utf-8") as f:
                mock_data = json.load(f)

            if not isinstance(mock_data, list):
                logger.error("[import_project_mock_data] Mock data should be a list")
                return False

            # Import mock data directly without transformation (new structure)
            transformed_data = []
            for item in mock_data:
                # Use the data as-is from JSON file (new structure with setting_item)
                project_data = {
                    "id": item.get("id"),
                    "setting_item": item.get("setting_item"),
                    "share": item.get("share", []),
                    "status_manage": item.get("status_manage"),
                    "created_at": item.get("created_at"),
                    "updated_at": item.get("updated_at"),
                    "deleted_at": item.get("deleted_at"),
                }

                # Remove None values for optional fields
                project_data = {k: v for k, v in project_data.items() if v is not None}
                transformed_data.append(project_data)

            # Insert data into database
            collection = await self.get_database_collection(
                self.project_collection_name
            )
            result = await collection.insert_many(transformed_data)

            if result.inserted_ids:
                logger.info(
                    f"[import_project_mock_data] Successfully imported {len(result.inserted_ids)} projects"
                )
                return True
            else:
                logger.error("[import_project_mock_data] Failed to import any projects")
                return False

        except Exception as e:
            error_message = f"[import_project_mock_data] Error importing project mock data: {e}"
            logger.error(error_message)
            save_exception_log_sync(e, error_message, __name__)

            raise

    async def count_users(self) -> int:
        """Count total users in collection"""
        logger.info("[count_users] Counting users")
        try:
            collection = await self.get_database_collection(self.user_collection_name)
            count = await collection.count_documents(
                {"$or": [{"deleted_at": None}, {"deleted_at": {"$exists": False}}]}
            )
            logger.info(f"[count_users] Found {count} users")
            return count
        except Exception as e:
            error_message = f"[count_users] Error counting users: {e}"
            logger.error(error_message)
            save_exception_log_sync(e, error_message, __name__)

            raise

    async def import_user_mock_data(self) -> bool:
        """Import user mock data from JSON file"""
        logger.info("[import_user_mock_data] Starting user mock data import")
        try:
            # Check if users already exist
            user_count = await self.count_users()
            if user_count > 0:
                logger.info(
                    "[import_user_mock_data] Users already exist, skipping import"
                )
                return True

            # Get path to mock data file
            current_dir = os.path.dirname(os.path.abspath(__file__))
            mock_data_path = os.path.join(
                current_dir, "..", "..", "mongodb-init", "mock-data", "user.json"
            )

            if not os.path.exists(mock_data_path):
                logger.error(
                    f"[import_user_mock_data] Mock data file not found: {mock_data_path}"
                )
                return False

            # Read and parse JSON file
            with open(mock_data_path, "r", encoding="utf-8") as f:
                mock_data = json.load(f)

            if not isinstance(mock_data, list):
                logger.error("[import_user_mock_data] Mock data should be a list")
                return False

            # Transform mock data to match User model
            transformed_data = []
            for item in mock_data:
                # Map the mock data structure to User model
                user_data = {
                    "user_id": item.get("user_id"),
                    "user_name": item.get("user_name"),
                    "email": item.get("email"),
                    "group": item.get("group", []),
                    "personal_projects": item.get("personal_projects", []),
                    "created_at": item.get("created_at"),
                    "updated_at": item.get("updated_at"),
                    "deleted_at": item.get("deleted_at"),
                }

                # Remove None values for optional fields
                user_data = {k: v for k, v in user_data.items() if v is not None}
                transformed_data.append(user_data)

            # Insert data into database
            collection = await self.get_database_collection(self.user_collection_name)
            result = await collection.insert_many(transformed_data)

            if result.inserted_ids:
                logger.info(
                    f"[import_user_mock_data] Successfully imported {len(result.inserted_ids)} users"
                )
                return True
            else:
                logger.error("[import_user_mock_data] Failed to import any users")
                return False

        except Exception as e:
            error_message = f"[import_user_mock_data] Error importing user mock data: {e}"
            logger.error(error_message)
            save_exception_log_sync(e, error_message, __name__)

            raise


